REVOKE ALL ON FUNCTION public.audit_staff_change() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.create_customer_profile() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.staff_has_role(text[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.staff_has_role(text[]) TO authenticated;
CREATE OR REPLACE FUNCTION public.preview_coupon(_code text,_items jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sub integer:=0; i jsonb; p public.products; q integer; c public.coupons; BEGIN IF jsonb_typeof(_items)<>'array' OR jsonb_array_length(_items) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid cart'; END IF; IF (SELECT count(DISTINCT value->>'productId') FROM jsonb_array_elements(_items))<>jsonb_array_length(_items) THEN RAISE EXCEPTION 'Duplicate cart item'; END IF; FOR i IN SELECT value FROM jsonb_array_elements(_items) LOOP q:=(i->>'quantity')::integer; IF q NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Invalid quantity'; END IF; SELECT * INTO p FROM public.products WHERE id=i->>'productId' AND status='active'; IF NOT FOUND THEN RAISE EXCEPTION 'Product unavailable'; END IF; sub:=sub+p.price_paise*q; END LOOP; SELECT * INTO c FROM public.coupons WHERE code=upper(trim(_code)) AND active AND starts_at<=now() AND ends_at>now() AND sub>=min_subtotal_paise; IF NOT FOUND THEN RETURN jsonb_build_object('valid',false,'discount',0); END IF; RETURN jsonb_build_object('valid',true,'discount',least(c.max_discount_paise,sub, floor(sub*c.percent/100.0)::integer)); END $$;
REVOKE ALL ON FUNCTION public.preview_coupon(text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.preview_coupon(text,jsonb) TO anon,authenticated;